import { NgTemplateOutlet } from '@angular/common';
import { booleanAttribute, ChangeDetectionStrategy, Component, computed, inject, input, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { BindModule } from 'primeng/bind';
import { FormsModule } from '@angular/forms';
import { Checkbox } from 'primeng/checkbox';
import { OrgChartNode } from 'primeng/types/organizationchart';
import { ChevronDown as ChevronDownIcon } from '@primeicons/angular/chevron-down';
import { ChevronUp as ChevronUpIcon } from '@primeicons/angular/chevron-up';
import type { OrganizationChart } from './organizationchart';
import { ORGANIZATIONCHART_INSTANCE } from './organizationchart-token';
import { OrganizationChartStyle } from './style/organizationchartstyle';

@Component({
    selector: '[pOrganizationChartNode]',
    standalone: true,
    imports: [NgTemplateOutlet, FormsModule, Checkbox, ChevronDownIcon, ChevronUpIcon, BindModule],
    template: `
        @if (node()) {
            <div
                [class]="cn(cx('node'), node()!.styleClass)"
                [style]="node()!.style"
                [attr.data-selectable]="dataSelectable()"
                [attr.data-selected]="dataSelected()"
                [attr.data-partial-selected]="dataPartialSelected()"
                [attr.data-collapsible]="dataCollapsible()"
                [attr.data-collapsed]="dataCollapsed()"
                [attr.tabindex]="nodeTabIndex()"
                (click)="onNodeClick($event, node()!)"
                (keydown.enter)="onNodeKeyDown($event, node()!)"
                (keydown.space)="onNodeKeyDown($event, node()!)"
                [pBind]="getPTOptions('node')"
            >
                <div [class]="cx('nodeContent')" [pBind]="ptm('nodeContent')">
                    @if (checkboxMode()) {
                        <p-checkbox
                            [binary]="true"
                            [ngModel]="selected()"
                            [indeterminate]="partialSelected()"
                            size="small"
                            [tabindex]="-1"
                            [readonly]="true"
                            [unstyled]="unstyled()"
                            [pt]="ptm('pcCheckbox')"
                            [attr.data-p-partialchecked]="partialSelected()"
                        >
                            @if (chart.checkboxIconTemplate()) {
                                <ng-template #icon let-checked>
                                    <ng-container *ngTemplateOutlet="chart.checkboxIconTemplate()!; context: { $implicit: checked, partialChecked: partialSelected() }"></ng-container>
                                </ng-template>
                            }
                        </p-checkbox>
                    }
                    @if (!chart.getTemplateForNode(node()!)) {
                        <span [class]="cx('label')" [pBind]="ptm('label')">{{ node()!.label }}</span>
                    } @else {
                        <ng-container *ngTemplateOutlet="chart.getTemplateForNode(node()!); context: { $implicit: node() }"></ng-container>
                    }
                </div>
                @if (isCollapsible()) {
                    @if (chart.collapseButtonTemplate()) {
                        <ng-container *ngTemplateOutlet="chart.collapseButtonTemplate()!; context: getCollapseButtonContext()"></ng-container>
                    } @else {
                        <button
                            type="button"
                            [class]="cx('collapseButton')"
                            [attr.aria-expanded]="!collapsed()"
                            [attr.aria-label]="toggleButtonAriaLabel()"
                            (click)="toggleNode($event, node()!)"
                            (keydown.enter)="toggleNode($event, node()!)"
                            (keydown.space)="toggleNode($event, node()!)"
                            [pBind]="getPTOptions('collapseButton')"
                        >
                            <span [class]="cx('collapseButtonIcon')" [pBind]="ptm('collapseButtonIcon')">
                                @if (!chart.togglerIconTemplate()) {
                                    @if (collapsed()) {
                                        <svg data-p-icon="chevron-down" />
                                    } @else {
                                        <svg data-p-icon="chevron-up" />
                                    }
                                } @else {
                                    <ng-template *ngTemplateOutlet="chart.togglerIconTemplate()!; context: { $implicit: !collapsed() }"></ng-template>
                                }
                            </span>
                        </button>
                    }
                }
            </div>
            @if (hasChildren() && !collapsed()) {
                <ul [class]="cx('subtree')" role="group" [pBind]="ptm('subtree')">
                    @for (child of children(); track child.key ?? $index) {
                        <li
                            [class]="cx('tree')"
                            role="treeitem"
                            [attr.data-level]="level() + 1"
                            [attr.aria-level]="level() + 1"
                            [attr.aria-expanded]="chart.getAriaExpanded(child)"
                            [attr.aria-selected]="chart.getAriaSelected(child)"
                            pOrganizationChartNode
                            [node]="child"
                            [level]="level() + 1"
                            [unstyled]="unstyled()"
                            [pt]="pt"
                            [pBind]="ptm('tree')"
                        ></li>
                    }
                </ul>
            }
        }
    `,
    encapsulation: ViewEncapsulation.None,
    changeDetection: ChangeDetectionStrategy.Default,
    providers: [OrganizationChartStyle, { provide: PARENT_INSTANCE, useExisting: OrganizationChartNode }]
})
export class OrganizationChartNode extends BaseComponent {
    node = input<OrgChartNode<any>>();

    root = input(undefined, { transform: booleanAttribute });

    level = input(1);

    chart = inject<OrganizationChart>(ORGANIZATIONCHART_INSTANCE);

    _componentStyle = inject(OrganizationChartStyle);

    children = computed(() => this.node()?.children ?? []);

    hasChildren = computed(() => this.children().length > 0);

    toggleNodeFn = this.toggleNode.bind(this);

    isSelectable = computed(() => {
        if (!this.chart.selectionMode()) return false;

        const flag = this.node()?.selectable;

        if (flag === false) return false;

        if (flag === true) return true;

        return !!this.chart.selectable();
    });

    isCollapsible = computed(() => {
        if (!this.hasChildren()) return false;

        const flag = this.node()?.collapsible;

        if (flag === false) return false;

        if (flag === true) return true;

        return !!this.chart.collapsible();
    });

    checkboxMode = computed(() => this.chart.selectionMode() === 'checkbox');

    selected = computed(() => this.chart.isSelected(this.node()!));

    partialSelected = computed(() => this.chart.isPartialSelected(this.node()!));

    collapsed = computed(() => this.isCollapsible() && this.chart.isCollapsed(this.node()!));

    dataSelectable = computed(() => this.isSelectable() || null);

    dataSelected = computed(() => this.selected() || null);

    dataPartialSelected = computed(() => this.partialSelected() || null);

    dataCollapsible = computed(() => this.isCollapsible() || null);

    dataCollapsed = computed(() => this.collapsed() || null);

    nodeTabIndex = computed(() => (this.isSelectable() ? 0 : -1));

    toggleButtonAriaLabel = computed(() => {
        const aria = this.config?.translation?.aria;

        return this.collapsed() ? (aria?.expand ?? 'Expand') : (aria?.collapse ?? 'Collapse');
    });

    getCollapseButtonContext() {
        return {
            $implicit: this.node(),
            expanded: !this.collapsed(),
            collapsed: this.collapsed(),
            childCount: this.children().length,
            toggle: this.toggleNodeFn
        };
    }

    getPTOptions(key: string) {
        return this.ptm(key, {
            context: {
                expanded: !this.collapsed(),
                selectable: this.isSelectable(),
                selected: this.selected(),
                toggleable: this.isCollapsible(),
                collapsed: this.collapsed(),
                active: this.selected()
            }
        });
    }

    onNodeClick(event: Event, node: OrgChartNode) {
        if (!this.isSelectable()) {
            return;
        }

        this.chart.onNodeClick(event, node);
    }

    onNodeKeyDown(event: Event, node: OrgChartNode) {
        if (!this.isSelectable()) {
            return;
        }

        event.preventDefault();
        this.chart.onNodeClick(event, node);
    }

    toggleNode(event: Event, node: OrgChartNode) {
        this.chart.onNodeToggle(event, node);
        event.preventDefault();
        event.stopPropagation();
    }
}
